/* HEXA BATTLEGROUNDS upgrade — PART 12 OF 31. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ create or replace function captain_use_item(p_token text, p_item text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; it items; v_qty int; v_dest text; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; select * into it from items where id = p_item; if it.id is null then raise exception 'BAD_ITEM'; end if; if it.kind = 'weapon' then raise exception 'USE_ATTACK'; end if; select qty into v_qty from inventory where team_id = t.id and item_id = p_item; if coalesce(v_qty, 0) < 1 then raise exception 'NO_ITEM'; end if; if t.state = 'recovery' and p_item <> 'medkit' then raise exception 'IN_RECOVERY'; end if; case p_item when 'medkit' then if t.state = 'recovery' then raise exception 'IN_RECOVERY'; end if; if t.hp >= _cfg(t.event_id, 'hp_max') then raise exception 'HP_FULL'; end if; perform _apply(t.id, 'medkit', 0, 0, (it.params ->> 'heal')::int, 0, null, 'Used a med kit'); when 'shield' then update teams set shield = least(_cfg(t.event_id, 'shield_max'), shield + (it.params ->> 'shield')::int) where id = t.id; when 'scanner' then update teams set scan_until = now() + _secs((it.params ->> 'seconds')::int) where id = t.id; when 'jammer' then update teams set jammed_until = now() + _secs((it.params ->> 'seconds')::int) where id = t.id; when 'beacon' then if t.beacon then raise exception 'ALREADY_ACTIVE'; end if; update teams set beacon = true where id = t.id; when 'extract' then if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; v_dest := _nearest_safe_xy(a.event_id, least(5, a.zone_stage + 1), (_team_xy(t))[1], (_team_xy(t))[2]); update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop'); update teams set state = 'idle', location_id = v_dest, pos_x = (_loc_xy(v_dest))[1], pos_y = (_loc_xy(v_dest))[2], pos_at = now(), travel_to = null, travel_from = null, travel_arrive_at = null, travel_fx = null, travel_fy = null, dropped = true, visit_missions = 0 where id = t.id; else raise exception 'BAD_ITEM'; end case; perform _add_item(t.id, p_item, -1); insert into ledger(arena_id, team_id, kind, ref, reason, actor) values (t.arena_id, t.id, 'item_used', null, p_item, 'captain'); perform _ping_team(t.id, 'item'); return jsonb_build_object('used', p_item, 'location', v_dest); end $$; create or replace function captain_attack(p_token text, p_target uuid, p_weapon text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_txy float8[]; v_dxy float8[]; p players; t teams; d teams; a arenas; it items; v_tpl text; v_bid uuid; v_secs int; v_qty int; v_al alliances; begin p := _auth_captain(p_token); perform 1 from teams where id in (p.team_id, p_target) order by id for update; select * into t from teams where id = p.team_id; select * into d from teams where id = p_target; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_BATTLES_NOW'; end if; if d.id is null or d.arena_id <> t.arena_id or d.id = t.id or not d.ready then raise exception 'BAD_TARGET'; end if; if t.state <> 'idle' or d.state <> 'idle' then raise exception 'TARGET_UNAVAILABLE'; end if; v_txy := _team_xy(t); v_dxy := _team_xy(d); if sqrt((v_txy[1] - v_dxy[1]) ^ 2 + (v_txy[2] - v_dxy[2]) ^ 2) > _cfg(t.event_id, 'engage_range') / 1000.0 then raise exception 'NOT_IN_RANGE'; end if; if t.attack_cooldown_until > now() then raise exception 'COOLDOWN'; end if; if d.protected_until > now() then raise exception 'TARGET_PROTECTED'; end if; if exists (select 1 from battles where status = 'active' and (attacker_id in (t.id, d.id) or defender_id in (t.id, d.id))) then raise exception 'ALREADY_IN_BATTLE'; end if; if exists (select 1 from mission_instances where team_id in (t.id, d.id) and status = 'active' and sync_round_id is not null) then raise exception 'TARGET_UNAVAILABLE'; end if; select * into it from items where id = p_weapon and kind = 'weapon'; if it.id is null then raise exception 'BAD_WEAPON'; end if; select qty into v_qty from inventory where team_id = t.id and item_id = p_weapon; if coalesce(v_qty, 0) < 1 then raise exception 'NO_ITEM'; end if; if (it.params ->> 'consumable')::boolean then perform _add_item(t.id, p_weapon, -1); end if; select * into v_al from alliances where status = 'active' and ((team_a = t.id and team_b = d.id) or (team_a = d.id and team_b = t.id)) for update; if v_al.id is not null then update alliances set status = 'betrayed' where id = v_al.id; perform _apply(t.id, 'betrayal', 0, 0, 0, -20, v_al.id::text, 'Betrayed an ally'); update arenas set threat = threat + 1 where id = a.id; perform _feed(a.id, 'alliance.betrayed', jsonb_build_object('by', t.number, 'victim', d.number)); end if; v_tpl := _pick_template(t.id, 'battle', array[it.params ->> 'tag']); if v_tpl is null then raise exception 'NO_TEMPLATE'; end if; v_secs := (it.params ->> 'seconds')::int; insert into battles(arena_id, attacker_id, defender_id, weapon, template_id, location_id, x, y, damage, deadline) values (a.id, t.id, d.id, p_weapon, v_tpl, coalesce(t.location_id, d.location_id), (v_txy[1] + v_dxy[1]) / 2, (v_txy[2] + v_dxy[2]) / 2, (it.params ->> 'damage')::int, now() + _secs(v_secs)) returning id into v_bid; perform _start_instance(t.id, v_tpl, t.location_id, v_bid, null, null, now() + _secs(v_secs)); perform _start_instance(d.id, v_tpl, t.location_id, v_bid, null, null, now() + _secs(v_secs)); update mission_instances set deadline = deadline + _secs(v_secs) where team_id in (t.id, d.id) and status = 'active' and kind <> 'battle'; perform _feed(a.id, 'battle.started', jsonb_build_object('attacker', t.number, 'defender', d.number, 'weapon', p_weapon, 'location', t.location_id)); perform _ping_team(d.id, 'battle'); perform _ping_arena(a.id, 'battle'); return jsonb_build_object('battle', v_bid); end $$;
